import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Toolkit Overview: Choose the Problem Before the Tool","description":"Route every template by starting point, skill practice, AI collaboration, artifact delivery, review, and recovery so a reader can build one complete action loop with minimal record-keeping.","frontmatter":{"title":"Toolkit Overview: Choose the Problem Before the Tool","socialImage":"/assets/social/templates-en.png","socialImageAlt":"Practice templates from baseline and practice to retest and next step","description":"Route every template by starting point, skill practice, AI collaboration, artifact delivery, review, and recovery so a reader can build one complete action loop with minimal record-keeping.","updated":"2026-10-04T00:00:00.000Z"},"headers":[],"relativePath":"en/templates/toolkit.md","filePath":"en/templates/toolkit.md","lastUpdated":1791072000000}'),o={name:"en/templates/toolkit.md"};function i(d,e,s,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="toolkit-overview-choose-the-problem-before-the-tool" tabindex="-1">Toolkit Overview: Choose the Problem Before the Tool <a class="header-anchor" href="#toolkit-overview-choose-the-problem-before-the-tool" aria-label="Permalink to &quot;Toolkit Overview: Choose the Problem Before the Tool&quot;">​</a></h1><p>Templates are not another course to collect. They are work sheets you can reuse: name the problem in front of you, preserve an unpolished sample, take one action, and let feedback decide what comes next.</p><p>If you do not know where to begin, choose one sheet. An incomplete sheet used on a real problem is more valuable than ten blank templates.</p><h2 id="first-ask-where-am-i-stuck" tabindex="-1">First Ask: Where Am I Stuck? <a class="header-anchor" href="#first-ask-where-am-i-stuck" aria-label="Permalink to &quot;First Ask: Where Am I Stuck?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Current block</th><th>First tool</th><th>Open next</th><th>What this tool cannot prove for you</th></tr></thead><tbody><tr><td>There are too many tools and I do not know how to fill them</td><td><a href="./toolkit-walkthrough">Toolkit Walkthrough</a></td><td><a href="./learning-state">Learning State</a></td><td>A synthetic example cannot prove the same plan fits you</td></tr><tr><td>No clear goal or baseline</td><td><a href="./learning-state">Learning State</a></td><td><a href="./english-diagnostic">English Diagnostic</a></td><td>It cannot choose a permanently correct direction</td></tr><tr><td>Preparing for a global role, English interview, or remote collaboration</td><td><a href="./interview-evidence">Job-search English Evidence Card</a></td><td><a href="./../threads/part-1/8-job-search-english">Job-search English</a></td><td>It cannot guarantee an offer or turn one level into a universal hiring line</td></tr><tr><td>Starting a 90-day cycle</td><td><a href="./90-day-cycle">90-Day Cycle Map</a></td><td><a href="./rhythm-ledger">Rhythm Ledger</a></td><td>It cannot guarantee success or persistence</td></tr><tr><td>Weekly rhythm keeps breaking</td><td><a href="./rhythm-ledger">Rhythm Ledger</a></td><td><a href="./weekly-review">Weekly Review</a></td><td>It cannot turn fatigue, illness, or responsibility into laziness</td></tr><tr><td>I have samples but cannot tell whether anything really changed</td><td><a href="./evidence-chain">Evidence Chain</a></td><td><a href="./../threads/part-3/5-evidence-and-transfer">Evidence</a></td><td>It cannot turn one smooth performance into stable ability</td></tr><tr><td>Reading moved me, but I do not know what remains seven days later</td><td><a href="./reader-field-note">Reader Field Note</a></td><td><a href="./evidence-chain">Evidence Chain</a></td><td>It cannot turn one personal experience into a universal effect</td></tr><tr><td>I am supporting a middle-school-age learner</td><td><a href="./family-learning-agreement">Family Learning Agreement</a></td><td><a href="./../threads/part-4/family-learning">Family Learning</a></td><td>It cannot choose a life for the learner, replace school, or diagnose difficulty</td></tr><tr><td>I recognise words but cannot use them</td><td><a href="./vocabulary-audit">Vocabulary Evidence Card</a></td><td><a href="./../threads/part-1/2-vocabulary">Vocabulary</a></td><td>It cannot replace contextual performance with card counts</td></tr><tr><td>I know the rule but still repeat errors in real expression</td><td><a href="./grammar-evidence">Grammar Evidence Card</a></td><td><a href="./../threads/part-1/grammar">Grammar</a></td><td>One corrected sentence, a style preference, or AI polish cannot prove stable grammar ability</td></tr><tr><td>I collect audio but still depend on captions or do not know what each replay should do</td><td><a href="./listening-audit">Listening Evidence Card</a></td><td><a href="./../threads/part-1/3-listening">Listening</a></td><td>Minutes, repetitions, caption understanding, and smooth shadowing cannot prove stable listening</td></tr><tr><td>I read documentation slowly, translate word by word, or cannot deliver after reading</td><td><a href="./reading-evidence">Reading Evidence Card</a></td><td><a href="./../threads/part-1/4-reading">Reading</a></td><td>Page count, highlights, translation, and tool summaries cannot prove independent understanding or verification</td></tr><tr><td>I sound fluent only with a script, fear accent difference, or freeze on follow-ups</td><td><a href="./speaking-evidence">Speaking Evidence Card</a></td><td><a href="./../threads/part-1/5-speaking">Speaking</a></td><td>Accent similarity, recognition scores, and one retake cannot prove stable interaction ability</td></tr><tr><td>I cannot leave my own draft, depend on sentence translation, or only have a tool-polished product</td><td><a href="./writing-evidence">Writing Evidence Card</a></td><td><a href="./../threads/part-1/6-writing">Writing</a></td><td>Fluent final text, automated scores, and one revision cannot prove accountable authorship or transfer</td></tr><tr><td>I do not know how to involve AI</td><td><a href="./ai-task-brief">AI Task Brief</a></td><td><a href="./ai-learning-log">AI Learning Log</a></td><td>It cannot turn a model response into a fact or final judgment</td></tr><tr><td>Too many new tools; unsure what to learn</td><td><a href="./ai-trend-radar">AI Trend Experiment</a></td><td><a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a></td><td>A launch demo or future hypothesis cannot establish benefit on my task</td></tr><tr><td>I have an idea but no deliverable</td><td><a href="./artifact-brief">Artifact Brief and Delivery Card</a></td><td><a href="./ai-project-scorecard">AI Project Scorecard</a></td><td>It cannot find users, carry responsibility, or prove a commercial result</td></tr><tr><td>I want to analyse a person or project story</td><td><a href="./ai-case-review">AI Case Review</a></td><td><a href="./../threads/part-2/narrative-and-evidence">Narrative and Evidence</a></td><td>It cannot turn a public narrative into an independent audit</td></tr><tr><td>I am handling a decision, attention, relationship, or recovery problem</td><td><a href="./life-practice-toolkit">Life Practice Toolkit</a></td><td><a href="./../threads/part-2/decision">Decision-Making</a> · <a href="./../threads/part-3/3-attention-and-judgment">Attention</a> · <a href="./../threads/part-2/relationships">Relationships</a> · <a href="./../threads/part-2/recovery">Recovery</a></td><td>It cannot replace medical, psychological, legal, or financial support</td></tr><tr><td>I want to care for someone, accept support, or share the weight of daily life</td><td><a href="./life-practice-toolkit">Care and Shared Responsibility Card</a></td><td><a href="./../threads/part-2/care-and-carry-on">Care</a></td><td>It cannot score love or require support beyond another person&#39;s willingness and capacity</td></tr><tr><td>Testing a business idea before adding features</td><td><a href="./startup-experiment">Startup Experiment</a></td><td><a href="./../threads/practice/customer-discovery">Customer Discovery</a></td><td>Praise, a free trial, or one payment does not establish sustainable demand</td></tr><tr><td>Diagnosing a blocked start or restarting once</td><td><a href="./consistency-plan">Consistency Plan</a></td><td><a href="./../threads/practice/discipline-and-consistency">Discipline and Consistency</a></td><td>One interruption does not establish a failure of character or willpower</td></tr><tr><td>Deciding whether an AI version can deliver</td><td><a href="./ai-evaluation">AI Evaluation Record</a></td><td><a href="./../threads/practice/ai-evaluation">AI Evaluation and Reliability</a></td><td>A small sample or human-repaired accuracy cannot guarantee production reliability</td></tr></tbody></table><h2 id="connect-the-tools-into-one-loop" tabindex="-1">Connect the Tools into One Loop <a class="header-anchor" href="#connect-the-tools-into-one-loop" aria-label="Permalink to &quot;Connect the Tools into One Loop&quot;">​</a></h2><p>For a first use, follow the complete <a href="./toolkit-walkthrough">synthetic cross-session AI-learning case</a>. Do not fill every template at once. Follow this order and keep only the evidence each step needs:</p><ol><li><strong>Locate</strong>: use <a href="./learning-state">Learning State</a> or <a href="./english-diagnostic">English Diagnostic</a> to name the real situation, baseline, and acceptance standard;</li><li><strong>Choose</strong>: use the <a href="./90-day-cycle">90-Day Cycle Map</a> for a longer cycle, or the <a href="./rhythm-ledger">Rhythm Ledger</a> for one week;</li><li><strong>Practice</strong>: choose a vocabulary, grammar, listening, reading, speaking, or writing evidence card; when the goal is an interview, use the <a href="./interview-evidence">Job-search English Evidence Card</a> to include unfamiliar follow-ups and asynchronous writing, and complete your own first version;</li><li><strong>Collaborate</strong>: when AI is useful, fill the <a href="./ai-task-brief">AI Task Brief</a>, then record the collaboration and your closed-AI performance in the <a href="./ai-learning-log">AI Learning Log</a>;</li><li><strong>Deliver</strong>: for a real audience, use the <a href="./artifact-brief">Artifact Brief and Delivery Card</a>; after a release or pilot, use the <a href="./ai-project-scorecard">AI Project Scorecard</a> to record quality, cost, risk, and rollback;</li><li><strong>Review</strong>: use the <a href="./evidence-chain">Evidence Chain</a> to place the first version, immediate performance, delayed retention, and transfer together, then use the <a href="./weekly-review">Weekly Review</a> to change one condition;</li><li><strong>Field note</strong>: when the action began from a chapter in this book, use the <a href="./reader-field-note">Reader Field Note</a> to record what entered action and what remained unusable.</li></ol><p>This is a returnable path. If a step reveals risk, lower capacity, or missing evidence, go back and reduce the task. Going back is not waste; it makes the next action more trustworthy.</p><h2 id="three-rules" tabindex="-1">Three Rules <a class="header-anchor" href="#three-rules" aria-label="Permalink to &quot;Three Rules&quot;">​</a></h2><h3 id="track-only-what-can-change-a-decision" tabindex="-1">Track Only What Can Change a Decision <a class="header-anchor" href="#track-only-what-can-change-a-decision" aria-label="Permalink to &quot;Track Only What Can Change a Decision&quot;">​</a></h3><p>If a number cannot help you continue, downgrade, change a variable, or stop, you do not need to record it for long. The purpose of a record is not to fill a page. It is to clarify the next step.</p><h3 id="a-first-version-should-be-human-made" tabindex="-1">A First Version Should Be Human-made <a class="header-anchor" href="#a-first-version-should-be-human-made" aria-label="Permalink to &quot;A First Version Should Be Human-made&quot;">​</a></h3><p>Complete the baseline, first version, and independent retest before AI enters or after it is closed whenever possible. A tool can explain, compare, and point out problems. It cannot manufacture the feeling of having learned.</p><h3 id="records-must-keep-boundaries" tabindex="-1">Records Must Keep Boundaries <a class="header-anchor" href="#records-must-keep-boundaries" aria-label="Permalink to &quot;Records Must Keep Boundaries&quot;">​</a></h3><p>Do not paste passwords, identity documents, exact addresses, customer data, medical privacy, or unauthorised third-party content into a template or model. For health, safety, legal, financial, or persistent loss-of-control concerns, contact a qualified professional or trusted support person first.</p><h2 id="a-minimum-beginning" tabindex="-1">A Minimum Beginning <a class="header-anchor" href="#a-minimum-beginning" aria-label="Permalink to &quot;A Minimum Beginning&quot;">​</a></h2><p>Write only four lines today:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The real problem I am solving:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The baseline evidence I already have:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The smallest output I will complete in 25–45 minutes:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Where I will preserve the evidence:</span></span></code></pre></div><p>When it is done, choose the tool closest to the task, give it a date, and set the next review time. Do not wait for every field to be complete. Starting is what makes the missing information concrete.</p><p>Related entry points: <a href="./toolkit-walkthrough">Toolkit Walkthrough</a> | <a href="./../threads/part-0/reader-guide">Reader&#39;s Guide: Put the Book Back into Life</a> | <a href="./../reference/glossary">Glossary of Terms and Methods</a> | <a href="./../threads/part-4/rhythm-and-compounding">Rhythm: Let Small Things Travel Through Time</a></p>`,21)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
